2	
3	/**
4	 * Derives an owner's region code — the {@code <REGION>} segment of the
5	 * {@code <REGION>-<HASH8>} {@code customerCode} and the source of the owner's locality.
6	 *
7	 * <p>The postcode is preferred: a four-digit postcode is mapped by inclusive range
8	 * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). When the postcode is absent or in no
9	 * known range, falls back to the fixed city-to-region table (Sydney-&gt;NSW,
10	 * Melbourne-&gt;VIC, Brisbane-&gt;QLD), otherwise {@code "UNKNOWN"}.
11	 */
12	public final class OwnerRegion {
13	
14	    private OwnerRegion() {
15	    }
16	
17	    /** Region derived from the postcode, falling back to the city, else {@code "UNKNOWN"}. */
18	    public static String fromPostcodeOrCity(String postcode, String city) {
19	        if (postcode != null && postcode.matches("[0-9]{4}")) {
20	            int value = Integer.parseInt(postcode);
21	            if (value >= 2000 && value <= 2099) return "NSW";
22	            if (value >= 3000 && value <= 3099) return "VIC";
23	            if (value >= 4000 && value <= 4099) return "QLD";
24	        }
25	        if ("Sydney".equals(city)) return "NSW";
26	        if ("Melbourne".equals(city)) return "VIC";
27	        if ("Brisbane".equals(city)) return "QLD";
28	        return "UNKNOWN";
29	    }
30	}
