2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	import org.springframework.samples.petclinic.rest.function.owner.OwnerRegion;
12	
13	import java.util.Collection;
14	import java.util.List;
15	
16	/**
17	 * Maps Owner & OwnerDto using Mapstruct
18	 */
19	@Mapper(uses = PetMapper.class)
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "displayName",
23	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
24	    @Mapping(target = "initials",
25	        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
26	    @Mapping(target = "locality",
27	        expression = "java(deriveLocality(owner))")
28	    @Mapping(target = "contactPreference",
29	        expression = "java(owner.getEmail() != null && !owner.getEmail().isBlank() ? \"EMAIL\" : \"PHONE\")")
30	    @Mapping(target = "identityKey",
31	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.identityKey(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId()))")
32	    @Mapping(target = "checkDigit",
33	        expression = "java(luhnCheckDigit(owner.getCustomerCode()))")
34	    @Mapping(target = "ageBand",
35	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.AgeBand.of(owner.getBirthDate(), owner.getRegistrationDate()))")
36	    @Mapping(target = "telephoneDisplay",
37	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.TelephoneDisplay.of(owner.getTelephone()))")
38	    OwnerDto toOwnerDto(Owner owner);
39	
40	    Owner toOwner(OwnerDto ownerDto);
41	
42	    @Mapping(target = "id", ignore = true)
43	    @Mapping(target = "pets", ignore = true)
44	    Owner toOwner(OwnerFieldsDto ownerDto);
45	
46	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
47	
48	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
49	
50	    /**
51	     * Derives the owner's locality (region) from the region-and-hash identity: the {@code <REGION>}
52	     * segment of the {@code <REGION>-<HASH8>} {@code customerCode}. The region embedded in the code
53	     * is itself derived (postcode preferred, then city) when the owner is created, so a postcode in a
54	     * known range still wins over the city. When no such code is present (e.g. legacy owners), falls
55	     * back to deriving the region live from the postcode/city via {@link OwnerRegion}.
56	     */
57	    default String deriveLocality(Owner owner) {
58	        String code = owner.getCustomerCode();
59	        if (code != null) {
60	            int dash = code.indexOf('-');
61	            if (dash > 0) {
62	                return code.substring(0, dash);
63	            }
64	        }
65	        return OwnerRegion.fromPostcodeOrCity(owner.getPostcode(), owner.getCity());
66	    }
67	
68	    /**
69	     * Computes the single Luhn check digit (0-9) over the digits contained in the given
70	     * customerCode. Non-digit characters (the separators) are ignored; from the rightmost digit
71	     * leftwards every second digit is doubled (subtracting 9 when the result exceeds 9), and the
72	     * check digit is {@code (10 - (sum % 10)) % 10}. Returns 0 when the code is null.
73	     */
74	    default int luhnCheckDigit(String customerCode) {
75	        if (customerCode == null) {
76	            return 0;
77	        }
78	        int sum = 0;
79	        boolean dbl = true;
80	        for (int i = customerCode.length() - 1; i >= 0; i--) {
81	            char c = customerCode.charAt(i);
82	            if (c < '0' || c > '9') {
83	                continue;
84	            }
85	            int d = c - '0';
86	            if (dbl) {
87	                d *= 2;
88	                if (d > 9) {
89	                    d -= 9;
90	                }
91	            }
92	            sum += d;
93	            dbl = !dbl;
94	        }
95	        return (10 - (sum % 10)) % 10;
96	    }
97	
98	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
99	        OwnerPageDto ownerPageDto = new OwnerPageDto();
100	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
101	        ownerPageDto.setPage(ownerPage.getNumber());
102	        ownerPageDto.setSize(ownerPage.getSize());
103	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
104	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
105	        return ownerPageDto;
106	    }
107	}
